/**
 * G09b-07 deterministic starter synthesis.
 *
 * Pure and dependency-free: given a kit analysis identity plus an
 * observed section inventory, produce the fixed `starter/` file set
 * (package.json, app/layout.tsx, app/page.tsx, README.md). The starter
 * is Skelet synthesis, never original website source:
 *
 * - structural placeholders only; observed site text is NEVER copied
 *   into starter files (a dedicated test feeds distinctive text and
 *   asserts its absence);
 * - every file carries a synthesis header;
 * - unknown server behavior and unobserved sections become explicit
 *   stubs and truncation notes, never fabricated content;
 * - section tags pass through HTML escaping (tag injection is tested).
 *
 * Deterministic: fixed templates, sorted inputs, capped section list.
 * Unknown request fields fail closed.
 */

export const STARTER_FILES = [
  "starter/package.json",
  "starter/app/layout.tsx",
  "starter/app/page.tsx",
  "starter/README.md",
] as const;

export const SYNTHESIS_HEADER = "Skelet synthesis — not original website source." as const;

const MAX_SECTIONS = 12;
const MAX_TAG_CHARS = 64;
const HEX64 = /^[0-9a-f]{64}$/;

/** Pinned Skelet synthesis defaults (not claims about the analyzed site). */
const PINNED_DEPS = {
  next: "14.2.5",
  react: "18.3.1",
  "react-dom": "18.3.1",
  tailwindcss: "3.4.10",
  typescript: "5.5.4",
} as const;

export interface StarterSection {
  tag: string;
  /**
   * Observed copy, accepted so callers can pass report sections
   * through untouched. NEVER emitted into starter files; present
   * only so tests can prove its absence.
   */
  text?: string;
}

export interface StarterRequest {
  analysisId: string;
  sections: StarterSection[];
  colorCount: number;
  spacingCount: number;
  hasTypography: boolean;
  truncated: boolean;
}

export interface StarterFile {
  path: string;
  content: string;
  bytes: number;
}

export class StarterError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.name = "StarterError";
    this.code = code;
  }
}

function invalid(message: string): StarterError {
  return new StarterError("starter/invalid-request", message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const KNOWN_FIELDS = new Set([
  "analysisId", "sections", "colorCount", "spacingCount", "hasTypography", "truncated",
]);

function nonNegativeInt(value: unknown, what: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0 || value > 100000) {
    throw invalid(`${what} must be an integer from 0 to 100000.`);
  }
  return value;
}

/**
 * Synthesize the fixed starter file set. Sections beyond the cap are
 * omitted with an explicit truncation note in the README; when the
 * caller already truncated upstream (`truncated: true`), the note says
 * so instead of claiming full coverage.
 */
export function synthesizeStarterArtifacts(input: StarterRequest): StarterFile[] {
  if (!isRecord(input)) throw invalid("Starter request must be an object.");
  for (const key of Object.keys(input)) {
    if (!KNOWN_FIELDS.has(key)) throw invalid(`Unknown starter field: ${key}.`);
  }
  if (typeof input.analysisId !== "string" || !HEX64.test(input.analysisId)) {
    throw invalid("Analysis ID must be 64 lowercase hex characters.");
  }
  if (!Array.isArray(input.sections) || input.sections.length > 500) {
    throw invalid("Starter sections must be a list of at most 500 entries.");
  }
  const tags: string[] = input.sections.map((section, index) => {
    if (!isRecord(section) || typeof section.tag !== "string" || section.tag.length === 0 || section.tag.length > MAX_TAG_CHARS) {
      throw invalid(`Starter section ${index} has an invalid tag.`);
    }
    if (section.text !== undefined && (typeof section.text !== "string" || section.text.length > 100000)) {
      throw invalid(`Starter section ${index} has invalid text.`);
    }
    return section.tag;
  });
  const colorCount = nonNegativeInt(input.colorCount, "Color count");
  const spacingCount = nonNegativeInt(input.spacingCount, "Spacing count");
  if (typeof input.hasTypography !== "boolean") throw invalid("Typography flag must be a boolean.");
  if (typeof input.truncated !== "boolean") throw invalid("Truncated flag must be a boolean.");

  const kept = tags.slice(0, MAX_SECTIONS);
  const omitted = tags.length - kept.length;
  const coverageNote = omitted > 0
    ? `${omitted} observed section(s) omitted beyond the ${MAX_SECTIONS}-section starter cap; add them by hand.`
    : input.truncated
      ? "Upstream inventory was truncated; this starter may omit observed sections."
      : "All observed sections are represented as placeholders.";

  const sectionBlocks = kept.map((tag) => {
    const safe = escapeHtml(tag);
    return [
      `      <section data-skelet-section="${safe}" className="mx-auto w-full max-w-3xl px-4 py-8">`,
      `        <h2 className="text-xl font-semibold">Section: ${safe}</h2>`,
      `        <p className="mt-2 text-sm opacity-70">Replace with your own copy. Observed tag: ${safe}.</p>`,
      `      </section>`,
    ].join("\n");
  }).join("\n");
  const pageBody = kept.length > 0 ? sectionBlocks : [
    `      <section className="mx-auto w-full max-w-3xl px-4 py-8">`,
    `        <h2 className="text-xl font-semibold">Empty starter</h2>`,
    `        <p className="mt-2 text-sm opacity-70">No sections were observed; add your own.</p>`,
    `      </section>`,
  ].join("\n");

  const files: Array<{ path: string; content: string }> = [
    {
      path: "starter/package.json",
      content: [
        `{`,
        `  "name": "skelet-starter",`,
        `  "private": true,`,
        `  "version": "0.1.0",`,
        `  "scripts": { "dev": "next dev", "build": "next build", "start": "next start" },`,
        `  "dependencies": {`,
        `    "next": "${PINNED_DEPS.next}",`,
        `    "react": "${PINNED_DEPS.react}",`,
        `    "react-dom": "${PINNED_DEPS["react-dom"]}"`,
        `  },`,
        `  "devDependencies": {`,
        `    "tailwindcss": "${PINNED_DEPS.tailwindcss}",`,
        `    "typescript": "${PINNED_DEPS.typescript}"`,
        `  }`,
        `}`,
        ``,
      ].join("\n"),
    },
    {
      path: "starter/app/layout.tsx",
      content: [
        `// ${SYNTHESIS_HEADER}`,
        `// Analysis ${input.analysisId}. Theme comes from the kit siblings:`,
        `// ../../shadcn-theme.css and ../../tailwind.theme.js.`,
        `import "../../shadcn-theme.css";`,
        ``,
        `export default function RootLayout({ children }: { children: React.ReactNode }) {`,
        `  return (`,
        `    <html lang="en">`,
        `      <body>{children}</body>`,
        `    </html>`,
        `  );`,
        `}`,
        ``,
      ].join("\n"),
    },
    {
      path: "starter/app/page.tsx",
      content: [
        `// ${SYNTHESIS_HEADER}`,
        `// Analysis ${input.analysisId}. Placeholders only; no observed site text is reproduced.`,
        `export default function Page() {`,
        `  return (`,
        `    <main>`,
        pageBody,
        `    </main>`,
        `  );`,
        `}`,
        ``,
      ].join("\n"),
    },
    {
      path: "starter/README.md",
      content: [
        `# Skelet starter`,
        ``,
        `> ${SYNTHESIS_HEADER}`,
        `> Analysis \`${input.analysisId}\`.`,
        ``,
        `## Token basis`,
        ``,
        `- Observed colors: ${colorCount}. Observed spacing entries: ${spacingCount}.`,
        `- Typography observed: ${input.hasTypography ? "yes" : "no"}.`,
        `- Theme values live in \`../shadcn-theme.css\`, \`../tailwind.theme.js\`, and \`../tokens.dtcg.json\`; this starter references them and defines nothing of its own.`,
        ``,
        `## Coverage`,
        ``,
        `- ${coverageNote}`,
        ``,
        `## Run it`,
        ``,
        "1. `npm install`",
        "2. `npm run dev` - stubs only; wire your own data and server behavior.",
        ``,
      ].join("\n"),
    },
  ];
  return files.map((file) => ({
    path: file.path,
    content: file.content,
    bytes: new TextEncoder().encode(file.content).byteLength,
  }));
}

TESTS:
import assert from "node:assert/strict";
import test from "node:test";

import {
  STARTER_FILES,
  StarterError,
  SYNTHESIS_HEADER,
  synthesizeStarterArtifacts,
} from "../src/starter-synthesis.ts";

const ANALYSIS = "d".repeat(64);

function request(overrides = {}) {
  return {
    analysisId: ANALYSIS,
    sections: [{ tag: "hero" }, { tag: "features" }],
    colorCount: 6,
    spacingCount: 4,
    hasTypography: true,
    truncated: false,
    ...overrides,
  };
}

function byPath(files) {
  return new Map(files.map((file) => [file.path, file.content]));
}

test("fixed file set with synthesis headers and byte counts", () => {
  const files = synthesizeStarterArtifacts(request());
  assert.deepEqual(files.map((file) => file.path), [...STARTER_FILES]);
  const contents = byPath(files);
  assert.ok((contents.get("starter/app/page.tsx") ?? "").includes(SYNTHESIS_HEADER));
  assert.ok((contents.get("starter/app/layout.tsx") ?? "").includes(SYNTHESIS_HEADER));
  assert.ok((contents.get("starter/README.md") ?? "").includes(SYNTHESIS_HEADER));
  assert.ok((contents.get("starter/README.md") ?? "").includes(ANALYSIS));
  for (const file of files) {
    assert.equal(file.bytes, new TextEncoder().encode(file.content).byteLength);
    assert.ok(file.bytes > 0);
  }
});

test("observed site text is never copied into the starter", () => {
  const distinctive = "quixotic-zebra-meridian-copy-never-repeat";
  const files = synthesizeStarterArtifacts(request({
    sections: [{ tag: "hero", text: distinctive }],
  }));
  for (const file of files) {
    assert.ok(!file.content.includes(distinctive), file.path);
  }
  const page = byPath(files).get("starter/app/page.tsx") ?? "";
  assert.ok(page.includes("Replace with your own copy"));
  assert.ok(page.includes("Section: hero"));
});

test("section tags are HTML-escaped", () => {
  const files = synthesizeStarterArtifacts(request({
    sections: [{ tag: `hero\"><script>alert(1)</script>` }],
  }));
  const page = byPath(files).get("starter/app/page.tsx") ?? "";
  assert.ok(!page.includes("<script>alert(1)</script>"));
  assert.ok(page.includes("&lt;script&gt;"));
  assert.ok(page.includes("&quot;&gt;"));
});

test("package.json carries pinned Skelet defaults and parses", () => {
  const files = synthesizeStarterArtifacts(request());
  const pkg = JSON.parse(byPath(files).get("starter/package.json") ?? "{}");
  assert.equal(pkg.private, true);
  assert.ok(typeof pkg.dependencies.next === "string");
  assert.ok(typeof pkg.dependencies.react === "string");
  assert.ok(typeof pkg.devDependencies.tailwindcss === "string");
});

test("token basis and coverage notes are honest", () => {
  const full = byPath(synthesizeStarterArtifacts(request())).get("starter/README.md") ?? "";
  assert.ok(full.includes("Observed colors: 6"));
  assert.ok(full.includes("All observed sections are represented as placeholders"));
  const many = Array.from({ length: 20 }, (_, i) => ({ tag: `s${i}` }));
  const trimmed = byPath(synthesizeStarterArtifacts(request({ sections: many }))).get("starter/README.md") ?? "";
  assert.ok(trimmed.includes("8 observed section(s) omitted beyond the 12-section starter cap"));
  const upstream = byPath(synthesizeStarterArtifacts(request({ truncated: true }))).get("starter/README.md") ?? "";
  assert.ok(upstream.includes("Upstream inventory was truncated"));
});

test("empty sections produce an explicit empty-state stub", () => {
  const page = byPath(synthesizeStarterArtifacts(request({ sections: [] }))).get("starter/app/page.tsx") ?? "";
  assert.ok(page.includes("Empty starter"));
  assert.ok(page.includes("No sections were observed"));
});

test("remaining validation branches fail closed", () => {
  assert.throws(
    () => synthesizeStarterArtifacts(request({ sections: [{ tag: "s", text: "x".repeat(100001) }] })),
    StarterError,
  );
  assert.throws(() => synthesizeStarterArtifacts(request({ sections: ["hero"] })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ sections: "hero" })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ colorCount: 1.5 })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ spacingCount: Number.NaN })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ truncated: 0 })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ analysisId: 42 })), StarterError);
});

test("layout references the kit theme siblings and the section cap holds", () => {
  const layout = byPath(synthesizeStarterArtifacts(request())).get("starter/app/layout.tsx") ?? "";
  assert.ok(layout.includes("../../shadcn-theme.css"));
  const many = Array.from({ length: 500 }, (_, i) => ({ tag: `s${i}` }));
  const files = synthesizeStarterArtifacts(request({ sections: many }));
  const page = byPath(files).get("starter/app/page.tsx") ?? "";
  assert.equal((page.match(/data-skelet-section=/g) ?? []).length, 12);
});
test("rebuilds are byte-identical", () => {
  const first = synthesizeStarterArtifacts(request());
  const second = synthesizeStarterArtifacts(request());
  assert.deepEqual(first, second);
});

test("malformed requests fail closed", () => {
  assert.throws(() => synthesizeStarterArtifacts(null), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ analysisId: "zz" })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ sections: [{ tag: "" }] })), StarterError);
  assert.throws(
    () => synthesizeStarterArtifacts(request({ sections: [{ tag: "x".repeat(65) }] })),
    StarterError,
  );
  assert.throws(() => synthesizeStarterArtifacts(request({ colorCount: -1 })), StarterError);
  assert.throws(() => synthesizeStarterArtifacts(request({ hasTypography: "yes" })), StarterError);
  assert.throws(
    () => synthesizeStarterArtifacts(request({ sections: Array.from({ length: 501 }, () => ({ tag: "s" })) })),
    StarterError,
  );
  assert.throws(() => synthesizeStarterArtifacts(request({ unknownField: 1 })), StarterError);
});
